-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/zones/Lower_Jeuno/npcs/_6t2.lua"]={["Path"]="scripts/zones/Lower_Jeuno/npcs/_6t2.lua",["SHA256"]="51890bd9935f0889e969c4f5b99a0311cc721ef0d506036a8d97acaf18879f65",["Text"]="-----------------------------------\n-- Area: Lower Jeuno\n-- Door: Merchant's House\n-- Starts & Finishes Quest: Save My Son\n-- Optional Involvement in Quest: Chocobo's Wounds, Path of the Beastmaster\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local aNewDawn      = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.A_NEW_DAWN)\n    local aNewDawnEvent = player:getCharVar('ANewDawn_Event')\n    local mLvl          = player:getMainLvl()\n\n    -- A New Dawn (BST AF3)\n    if\n        player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.SCATTERED_INTO_SHADOW) == xi.questStatus.QUEST_COMPLETED and\n        aNewDawn == xi.questStatus.QUEST_AVAILABLE\n    then\n        if\n            player:getMainJob() == xi.job.BST and\n            mLvl >= 50\n        then\n            if aNewDawnEvent == 0 then\n                player:startEvent(5)\n            elseif aNewDawnEvent == 1 then\n                player:startEvent(4)\n            end\n        else\n            player:startEvent(1)\n        end\n\n    elseif aNewDawn == xi.questStatus.QUEST_ACCEPTED then\n        if aNewDawnEvent == 2 then\n            player:startEvent(2)\n        elseif aNewDawnEvent >= 4 then\n            player:startEvent(3)\n        end\n\n    elseif\n        aNewDawn == xi.questStatus.QUEST_COMPLETED and\n        aNewDawnEvent == 6\n    then\n        player:startEvent(0)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 5 then\n        player:setCharVar('ANewDawn_Event', 1)\n        if option == 1 then\n            player:addQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.A_NEW_DAWN)\n            player:setCharVar('ANewDawn_Event', 2)\n        end\n    elseif csid == 4 and option == 1 then\n        player:addQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.A_NEW_DAWN)\n        player:setCharVar('ANewDawn_Event', 2)\n    elseif csid == 0 then\n        player:setCharVar('ANewDawn_Event', 0)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Lower_Jeuno/npcs/_6tc.lua"]={["Path"]="scripts/zones/Lower_Jeuno/npcs/_6tc.lua",["SHA256"]="d6438fb422645dd5dbb27a43c1bc1c4ddaf7f6541a137d8003830632ab3ead78",["Text"]="-----------------------------------\n-- Area: Lower Jeuno\n--  NPC: Door: \"Neptune's Spire\"\n-- Starts and Finishes Quest: Beat Around the Bushin\n-- ZM 17 cutscene\n-- !pos 35 0 -15 245\n-----------------------------------\nlocal ID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.BEAT_AROUND_THE_BUSHIN) == xi.questStatus.QUEST_ACCEPTED then\n        if\n            trade:hasItemQty(xi.item.WYRM_BEARD, 1) and\n            trade:getItemCount() == 1 and\n            player:getCharVar('BeatAroundTheBushin') == 2\n        then\n            player:startEvent(156) -- After trade Wyrm Beard\n\n        elseif\n            trade:hasItemQty(xi.item.BEHEMOTH_TONGUE, 1) and\n            trade:getItemCount() == 1 and\n            player:getCharVar('BeatAroundTheBushin') == 4\n        then\n            player:startEvent(157) -- After trade Behemoth Tongue\n\n        elseif\n            trade:hasItemQty(xi.item.ADAMANTOISE_EGG, 1) and\n            trade:getItemCount() == 1 and\n            player:getCharVar('BeatAroundTheBushin') == 6\n        then\n            player:startEvent(158) -- After trade Adamantoise Egg\n\n        elseif\n            trade:hasItemQty(xi.item.BROWN_BELT, 1) and\n            trade:getItemCount() == 1 and\n            player:getCharVar('BeatAroundTheBushin') == 7\n        then\n            player:startEvent(159) -- After trade Brown Belt, Finish Quest \"Beat around the Bushin\"\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if player:getCharVar('BeatAroundTheBushin') == 1 then\n        player:startEvent(155) -- Start Quest \"Beat around the Bushin\"\n\n    elseif player:hasKeyItem(xi.keyItem.TENSHODO_MEMBERS_CARD) then\n        player:startEvent(105) -- Open the door\n\n    else\n        player:messageSpecial(ID.text.ITS_LOCKED)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 155 then\n        player:addQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.BEAT_AROUND_THE_BUSHIN)\n        player:setCharVar('BeatAroundTheBushin', 2)\n    elseif csid == 156 then\n        player:setCharVar('BeatAroundTheBushin', 3)\n        player:tradeComplete()\n    elseif csid == 157 then\n        player:setCharVar('BeatAroundTheBushin', 5)\n        player:tradeComplete()\n    elseif csid == 158 then\n        player:setCharVar('BeatAroundTheBushin', 7)\n        player:tradeComplete()\n    elseif csid == 159 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.BLACK_BELT)\n        else\n            player:addTitle(xi.title.BLACK_BELT)\n            player:addItem(xi.item.BLACK_BELT)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.BLACK_BELT)\n            player:setCharVar('BeatAroundTheBushin', 0)\n            player:addFame(xi.fameArea.NORG, 60)\n            player:tradeComplete()\n            player:completeQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.BEAT_AROUND_THE_BUSHIN)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Metalworks/npcs/Ferghus.lua"]={["Path"]="scripts/zones/Metalworks/npcs/Ferghus.lua",["SHA256"]="20fa10e0cb246e2ce79862c760c088bca80c059376b77fd34560c609b8f30112",["Text"]="-----------------------------------\n-- Area: Metalworks\n--  NPC: Ferghus\n-- Starts Quest: Too Many Chefs (1, 86)\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local tooManyChefs = player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.TOO_MANY_CHEFS)\n    local pFame = player:getFameLevel(xi.fameArea.BASTOK)\n\n    if\n        xi.settings.main.ENABLE_WOTG == 1 and\n        tooManyChefs == xi.questStatus.QUEST_AVAILABLE and\n        pFame >= 5\n    then\n        player:startEvent(946) -- Start Quest \"Too Many Chefs\"\n    elseif player:getCharVar('TOO_MANY_CHEFS') == 4 then -- after trade to Leonhardt\n        player:startEvent(947)\n    else\n        player:startEvent(420) -- Standard\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 946 and option == 0 then\n        player:addQuest(xi.questLog.BASTOK, xi.quest.id.bastok.TOO_MANY_CHEFS)\n        player:setCharVar('TOO_MANY_CHEFS', 1)\n    elseif csid == 947 then\n        player:setCharVar('TOO_MANY_CHEFS', 5)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Mhaura/npcs/Lacia.lua"]={["Path"]="scripts/zones/Mhaura/npcs/Lacia.lua",["SHA256"]="490ab73ad48fe34774af72861b8b607d3c0a00cccf1cac14cf829cdcb3496d9b",["Text"]="-----------------------------------\n-- Area: Mhaura\n--  NPC: Lacia\n-- Starts Quest: Trial Size Trial By Lightning\n-----------------------------------\nlocal ID = zones[xi.zone.MHAURA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        trade:hasItemQty(xi.item.MINI_TUNING_FORK_OF_LIGHTNING, 1) and\n        player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.TRIAL_SIZE_TRIAL_BY_LIGHTNING) == xi.questStatus.QUEST_ACCEPTED and\n        player:getMainJob() == xi.job.SMN\n    then\n        player:startEvent(10026, 0, xi.item.MINI_TUNING_FORK_OF_LIGHTNING, 5, 20)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local trialSizeLightning = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.TRIAL_SIZE_TRIAL_BY_LIGHTNING)\n\n    if\n        player:getMainLvl() >= 20 and\n        player:getMainJob() == xi.job.SMN and\n        trialSizeLightning == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 2\n    then\n        --Requires player to be Summoner at least lvl 20\n        player:startEvent(10025, 0, xi.item.MINI_TUNING_FORK_OF_LIGHTNING, 5, 20)     --mini tuning fork of lightning, zone, level\n    elseif trialSizeLightning == xi.questStatus.QUEST_ACCEPTED then\n        local hasLightningFork = player:hasItem(xi.item.MINI_TUNING_FORK_OF_LIGHTNING)\n\n        if hasLightningFork then\n            player:startEvent(10018) --Dialogue given to remind player to be prepared\n        else\n            player:startEvent(10029, 0, xi.item.MINI_TUNING_FORK_OF_LIGHTNING, 5, 20) --Need another mini tuning fork\n        end\n    elseif trialSizeLightning == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(10028) --Defeated Ramuh\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 10025 and option == 1 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MINI_TUNING_FORK_OF_LIGHTNING)\n        else\n            player:addQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.TRIAL_SIZE_TRIAL_BY_LIGHTNING)\n            player:addItem(xi.item.MINI_TUNING_FORK_OF_LIGHTNING)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MINI_TUNING_FORK_OF_LIGHTNING)\n        end\n    elseif csid == 10029 and option == 1 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MINI_TUNING_FORK_OF_LIGHTNING)\n        else\n            player:addItem(xi.item.MINI_TUNING_FORK_OF_LIGHTNING)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MINI_TUNING_FORK_OF_LIGHTNING)\n        end\n    elseif csid == 10026 and option == 1 then\n        xi.teleport.to(player, xi.teleport.id.CLOISTER_OF_STORMS)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Mhaura/npcs/Nereus.lua"]={["Path"]="scripts/zones/Mhaura/npcs/Nereus.lua",["SHA256"]="f9c0d017a61fcbae0d03676c106c1f78d268a16f3a6c0949381e030b6d48aee5",["Text"]="-----------------------------------\n-- Area: Mhaura\n--  NPC: Nereus\n-- Starts and ends repeteable quest A_POTTERS_PREFERENCE\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_POTTERS_PREFERENCE) == xi.questStatus.QUEST_ACCEPTED or\n        player:getCharVar('QuestAPotterPrefeRepeat_var') == 1\n    then\n        if npcUtil.tradeHas(trade, xi.item.DISH_OF_GUSGEN_CLAY) then\n            player:startEvent(113) -- quest done!\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_POTTERS_PREFERENCE) == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 6\n    then\n        player:startEvent(111, xi.item.DISH_OF_GUSGEN_CLAY) -- start quest A Potter's Preference\n    elseif player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_POTTERS_PREFERENCE) == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(114, xi.item.DISH_OF_GUSGEN_CLAY) -- get me dish_of_gusgen_clay  as soon as you can\n    elseif player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_POTTERS_PREFERENCE) == xi.questStatus.QUEST_COMPLETED then\n        if\n            player:getCharVar('QuestAPotterPrefeCompDay_var') + 8 <= VanadielUniqueDay()\n        then\n            -- eight days after completion, allow to do the quest again\n            player:startEvent(112) -- repeat quest\n        else\n            player:startEvent(115) -- i have enough for now, come later\n        end\n    else\n        player:startEvent(110) --standar dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 111 and option == 1 then  --accept quest\n        player:addQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_POTTERS_PREFERENCE)\n    elseif csid == 113 then --quest completed\n        player:confirmTrade()\n        player:addFame(xi.fameArea.WINDURST, 60)\n        npcUtil.giveCurrency(player, 'gil', 2160)\n        player:setCharVar('QuestAPotterPrefeRepeat_var', 0)\n        player:setCharVar('QuestAPotterPrefeCompDay_var', VanadielUniqueDay())\n        player:completeQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_POTTERS_PREFERENCE)\n    elseif csid == 112 then --repeat quest\n        player:setCharVar('QuestAPotterPrefeRepeat_var', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Mhaura/npcs/Orlando.lua"]={["Path"]="scripts/zones/Mhaura/npcs/Orlando.lua",["SHA256"]="38cf10394e9d5e0a41e874678847324a0c76584dc2351ed52b3bf94488116d39",["Text"]="-----------------------------------\n-- Area: Mhaura\n--  NPC: Orlando\n-- !pos -37.268 -9 58.047 249\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local questStatus = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ORLANDOS_ANTIQUES)\n    local itemID = trade:getItemId()\n    local itemList =\n    {\n        {   564, 200 }, -- Fingernail Sack\n        {   565, 250 }, -- Teeth Sack\n        {   566, 200 }, -- Goblin Cup\n        {   568, 120 }, -- Goblin Die\n        {   656, 600 }, -- Beastcoin\n        {   748, 900 }, -- Gold Beastcoin\n        {   749, 800 }, -- Mythril Beastcoin\n        {   750, 750 }, -- Silver Beastcoin\n        {   898, 120 }, -- Chicken Bone\n        {   900, 100 }, -- Fish Bone\n        { 16995, 150 }, -- Rotten Meat\n    }\n\n    for x, item in pairs(itemList) do\n        if\n            questStatus == xi.questStatus.QUEST_ACCEPTED or\n            player:getLocalVar('OrlandoRepeat') == 1\n        then\n            if item[1] == itemID then\n                if trade:hasItemQty(itemID, 8) and trade:getItemCount() == 8 then\n                    -- Correct amount, valid item.\n                    player:setCharVar('ANTIQUE_PAYOUT', xi.settings.main.GIL_RATE * item[2])\n                    player:startEvent(102, xi.settings.main.GIL_RATE * item[2], itemID)\n                elseif trade:getItemCount() < 8 then\n                    -- Wrong amount, but valid item.\n                    player:startEvent(104)\n                end\n            end\n        end\n    end\nend\n\n-- TODO: Event 106 needs confirmation if/when it happens\nentity.onTrigger = function(player, npc)\n    local questStatus = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ORLANDOS_ANTIQUES)\n\n    if\n        player:getFameLevel(xi.fameArea.WINDURST) >= 2 and\n        player:hasKeyItem(xi.keyItem.CHOCOBO_LICENSE)\n    then\n        if questStatus ~= xi.questStatus.QUEST_AVAILABLE then\n            player:startEvent(103)\n        elseif questStatus == xi.questStatus.QUEST_AVAILABLE then\n            player:startEvent(101)\n        end\n    else\n        player:startEvent(100)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    local questStatus = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ORLANDOS_ANTIQUES)\n    local payout = player:getCharVar('ANTIQUE_PAYOUT')\n\n    if csid == 101 then\n        player:addQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ORLANDOS_ANTIQUES)\n    elseif csid == 102 then\n        player:tradeComplete()\n        player:addFame(xi.fameArea.WINDURST, 10)\n        npcUtil.giveCurrency(player, 'gil', payout)\n        player:completeQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ORLANDOS_ANTIQUES)\n        player:setCharVar('ANTIQUE_PAYOUT', 0)\n        player:setLocalVar('OrlandoRepeat', 0)\n    elseif csid == 103 then\n        if questStatus == xi.questStatus.QUEST_COMPLETED then\n            player:setLocalVar('OrlandoRepeat', 1)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Mhaura/npcs/Ripapa.lua"]={["Path"]="scripts/zones/Mhaura/npcs/Ripapa.lua",["SHA256"]="654979a2eff67dfcc4dca6b573b837575e0c3f2a138a5fbfe2f502c24f7853b5",["Text"]="-----------------------------------\n-- Area: Mhaura\n--  NPC: Ripapa\n-- Starts and Finishes Quest: Trial by Lightning\n-- !pos 29 -15 55 249\n-----------------------------------\nlocal ID = zones[xi.zone.MHAURA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local trialByLightning = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.TRIAL_BY_LIGHTNING)\n    local hasWhisperOfStorms = player:hasKeyItem(xi.keyItem.WHISPER_OF_STORMS)\n    local carbuncleDebacle = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CARBUNCLE_DEBACLE)\n    local carbuncleDebacleProgress = player:getCharVar('CarbuncleDebacleProgress')\n\n    -----------------------------------\n    -- Carbunlce Debacle\n    if\n        carbuncleDebacle == xi.questStatus.QUEST_ACCEPTED and\n        carbuncleDebacleProgress == 2\n    then\n        player:startEvent(10022) -- get the lighning pendulum lets go to Cloister of Storms\n    elseif\n        carbuncleDebacle == xi.questStatus.QUEST_ACCEPTED and\n        carbuncleDebacleProgress == 3 and\n        not player:hasItem(xi.item.LIGHTNING_PENDULUM)\n    then\n        player:startEvent(10023, 0, xi.item.LIGHTNING_PENDULUM, 0, 0, 0, 0, 0, 0) -- \"lost the pendulum?\"\n    -----------------------------------\n    -- Trial by Lightning\n    elseif\n        (trialByLightning == xi.questStatus.QUEST_AVAILABLE and player:getFameLevel(xi.fameArea.WINDURST) >= 6) or\n        (trialByLightning == xi.questStatus.QUEST_COMPLETED and GetSystemTime() > player:getCharVar('TrialByLightning_date'))\n    then\n        player:startEvent(10016, 0, xi.keyItem.TUNING_FORK_OF_LIGHTNING) -- Start and restart quest \"Trial by Lightning\"\n    elseif\n        trialByLightning == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.TUNING_FORK_OF_LIGHTNING) and\n        not hasWhisperOfStorms\n    then\n        player:startEvent(10024, 0, xi.keyItem.TUNING_FORK_OF_LIGHTNING) -- Defeat against Ramuh : Need new Fork\n    elseif\n        trialByLightning == xi.questStatus.QUEST_ACCEPTED and\n        not hasWhisperOfStorms\n    then\n        player:startEvent(10017, 0, xi.keyItem.TUNING_FORK_OF_LIGHTNING, 5)\n    elseif\n        trialByLightning == xi.questStatus.QUEST_ACCEPTED and\n        hasWhisperOfStorms\n    then\n        local numitem = 0\n\n        if player:hasItem(xi.item.RAMUHS_STAFF) then\n            numitem = numitem + 1\n        end\n\n        if player:hasItem(xi.item.LIGHTNING_BELT) then\n            numitem = numitem + 2\n        end\n\n        if player:hasItem(xi.item.LIGHTNING_RING) then\n            numitem = numitem + 4\n        end\n\n        if player:hasItem(xi.item.ELDER_BRANCH) then\n            numitem = numitem + 8\n        end\n\n        if player:hasSpell(xi.magic.spell.RAMUH) then\n            numitem = numitem + 32\n        end  -- Ability to summon Ramuh\n\n        player:startEvent(10019, 0, xi.keyItem.TUNING_FORK_OF_LIGHTNING, 5, 0, numitem)\n    else\n        player:startEvent(10020) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 10016 and option == 1 then\n        if player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.TRIAL_BY_LIGHTNING) == xi.questStatus.QUEST_COMPLETED then\n            player:delQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.TRIAL_BY_LIGHTNING)\n        end\n\n        player:addQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.TRIAL_BY_LIGHTNING)\n        player:setCharVar('TrialByLightning_date', 0)\n        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_LIGHTNING)\n    elseif csid == 10024 then\n        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_LIGHTNING)\n    elseif csid == 10019 then\n        local item = 0\n        if option == 1 then\n            item = xi.item.RAMUHS_STAFF\n        elseif option == 2 then\n            item = xi.item.LIGHTNING_BELT\n        elseif option == 3 then\n            item = xi.item.LIGHTNING_RING\n        elseif option == 4 then\n            item = xi.item.ELDER_BRANCH\n        end\n\n        if player:getFreeSlotsCount() == 0 and (option ~= 5 or option ~= 6) then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, item)\n        else\n            if option == 5 then\n                npcUtil.giveCurrency(player, 'gil', 10000)\n            elseif option == 6 then\n                player:addSpell(xi.magic.spell.RAMUH) -- Ramuh Spell\n                player:messageSpecial(ID.text.RAMUH_UNLOCKED, 0, 0, 5)\n            else\n                player:addItem(item)\n                player:messageSpecial(ID.text.ITEM_OBTAINED, item) -- Item\n            end\n\n            player:addTitle(xi.title.HEIR_OF_THE_GREAT_LIGHTNING)\n            player:delKeyItem(xi.keyItem.WHISPER_OF_STORMS) --Whisper of Storms, as a trade for the above rewards\n            player:setCharVar('TrialByLightning_date', JstMidnight())\n            player:addFame(xi.fameArea.WINDURST, 60)\n            player:completeQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.TRIAL_BY_LIGHTNING)\n        end\n    elseif csid == 10022 or csid == 10023 then\n        if player:getFreeSlotsCount() ~= 0 then\n            player:addItem(xi.item.LIGHTNING_PENDULUM)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.LIGHTNING_PENDULUM)\n            player:setCharVar('CarbuncleDebacleProgress', 3)\n        else\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.LIGHTNING_PENDULUM)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Nashmau/npcs/Dnegan.lua"]={["Path"]="scripts/zones/Nashmau/npcs/Dnegan.lua",["SHA256"]="6a4dcc74fdd4748bed0e9092389297d3980db9f73a562427406e8a2d549a8c47",["Text"]="-----------------------------------\n-- Area: Nashmau\n--  NPC: Dnegan\n-- Involved in quest: Wayward Automaton\n-- !pos 29.89 -6 55.83 53\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local theWaywardAutomaton = player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_WAYWARD_AUTOMATON)\n    local theWaywardAutomatonProgress = player:getCharVar('TheWaywardAutomatonProgress')\n    local operationTeatimeProgress = player:getCharVar('OperationTeatimeProgress')\n\n    -- Quest: The WayWard Automaton\n    if\n        theWaywardAutomaton == xi.questStatus.QUEST_ACCEPTED and\n        theWaywardAutomatonProgress == 1\n    then\n        player:startEvent(289) -- he tells u to go Caedarva Mire\n    elseif theWaywardAutomatonProgress == 2 then\n        player:startEvent(289) -- Hint to go to Caedarva Mire\n\n    -- Quest: Operation Teatime\n    elseif\n        operationTeatimeProgress == 2 and\n        player:getCharVar('OTT_DayWait') ~= VanadielUniqueDay()\n    then\n        player:startEvent(290) -- CS for Chai\n    else\n        player:startEvent(288)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 289 then\n        player:setCharVar('TheWaywardAutomatonProgress', 2)\n    elseif csid == 290 and option == 0 then\n        player:setCharVar('OTT_DayWait', VanadielUniqueDay())\n    elseif csid == 290 and option == 1 then\n        player:setCharVar('OperationTeatimeProgress', 3)\n        player:setCharVar('OTT_DayWait', 0)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Norg/npcs/Edal-Tahdal.lua"]={["Path"]="scripts/zones/Norg/npcs/Edal-Tahdal.lua",["SHA256"]="538fc9bac6e7431bdd421e24d00a683a419fe5f84ce741cb46feb3d7a82ef180",["Text"]="-----------------------------------\n-- Area: Norg\n--  NPC: Edal-Tahdal\n-- Starts and Finishes Quest: Trial by Water\n-- !pos -13 1 -20 252\n-----------------------------------\nlocal ID = zones[xi.zone.NORG]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local trialByWater = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_WATER)\n    local hasWhisperOfTides = player:hasKeyItem(xi.keyItem.WHISPER_OF_TIDES)\n\n    if\n        (trialByWater == xi.questStatus.QUEST_AVAILABLE and player:getFameLevel(xi.fameArea.NORG) >= 4) or\n        (trialByWater == xi.questStatus.QUEST_COMPLETED and GetSystemTime() > player:getCharVar('TrialByWater_date'))\n    then\n        player:startEvent(109, 0, xi.keyItem.TUNING_FORK_OF_WATER) -- Start and restart quest 'Trial by Water'\n    elseif\n        trialByWater == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.TUNING_FORK_OF_WATER) and\n        not hasWhisperOfTides\n    then\n        player:startEvent(190, 0, xi.keyItem.TUNING_FORK_OF_WATER) -- Defeat against Avatar : Need new Fork\n    elseif trialByWater == xi.questStatus.QUEST_ACCEPTED and not hasWhisperOfTides then\n        player:startEvent(110, 0, xi.keyItem.TUNING_FORK_OF_WATER, 2)\n    elseif trialByWater == xi.questStatus.QUEST_ACCEPTED and hasWhisperOfTides then\n        local numitem = 0\n\n        if player:hasItem(xi.item.LEVIATHANS_ROD) then\n            numitem = numitem + 1\n        end\n\n        if player:hasItem(xi.item.WATER_BELT) then\n            numitem = numitem + 2\n        end\n\n        if player:hasItem(xi.item.WATER_RING) then\n            numitem = numitem + 4\n        end\n\n        if player:hasItem(xi.item.EYE_OF_NEPT) then\n            numitem = numitem + 8\n        end\n\n        if player:hasSpell(xi.magic.spell.LEVIATHAN) then\n            numitem = numitem + 32\n        end  -- Ability to summon Leviathan\n\n        player:startEvent(112, 0, xi.keyItem.TUNING_FORK_OF_WATER, 2, 0, numitem)\n    else\n        player:startEvent(113) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 109 and option == 1 then\n        if player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_WATER) == xi.questStatus.QUEST_COMPLETED then\n            player:delQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_WATER)\n        end\n\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_WATER)\n        player:setCharVar('TrialByWater_date', 0)\n        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_WATER)\n    elseif csid == 190 then\n        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_WATER)\n    elseif csid == 112 then\n        local item = 0\n        if option == 1 then\n            item = xi.item.LEVIATHANS_ROD\n        elseif option == 2 then\n            item = xi.item.WATER_BELT\n        elseif option == 3 then\n            item = xi.item.WATER_RING\n        elseif option == 4 then\n            item = xi.item.EYE_OF_NEPT\n        end\n\n        if player:getFreeSlotsCount() == 0 and (option ~= 5 or option ~= 6) then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, item)\n        else\n            if option == 5 then\n                npcUtil.giveCurrency(player, 'gil', 10000)\n            elseif option == 6 then\n                player:addSpell(xi.magic.spell.LEVIATHAN) -- Avatar\n                player:messageSpecial(ID.text.AVATAR_UNLOCKED, 0, 0, 2)\n            else\n                player:addItem(item)\n                player:messageSpecial(ID.text.ITEM_OBTAINED, item) -- Item\n            end\n\n            player:addTitle(xi.title.HEIR_OF_THE_GREAT_WATER)\n            player:delKeyItem(xi.keyItem.WHISPER_OF_TIDES) --Whisper of Tides, as a trade for the above rewards\n            player:setCharVar('TrialByWater_date', JstMidnight())\n            player:addFame(xi.fameArea.NORG, 60)\n            player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_WATER)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Norg/npcs/Magephaud.lua"]={["Path"]="scripts/zones/Norg/npcs/Magephaud.lua",["SHA256"]="27214f48f12ef951a74fd755a53b7d400bedf3083eb10def0669a81b35be991b",["Text"]="-----------------------------------\n-- Area: Norg\n--  NPC: Magephaud\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local everyonesGrudge = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVERYONES_GRUDGE)\n    if everyonesGrudge == xi.questStatus.QUEST_ACCEPTED then\n        if\n            trade:hasItemQty(xi.item.GOLD_BEASTCOIN, 3) and\n            trade:getItemCount() == 3\n        then\n            player:startEvent(118, xi.item.GOLD_BEASTCOIN)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local nFame = player:getFameLevel(xi.fameArea.NORG)\n\n    if\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVERYONES_GRUDGE) == xi.questStatus.QUEST_AVAILABLE and\n        player:getCharVar('EVERYONES_GRUDGE_KILLS') >= 1 and\n        nFame >= 2\n    then\n        player:startEvent(116, xi.item.GOLD_BEASTCOIN)  -- Quest start - you have tonberry kills?! I got yo back ^.-\n    elseif player:getCharVar('EveryonesGrudgeStarted') == 1 then\n        player:startEvent(117, xi.item.GOLD_BEASTCOIN)\n    elseif player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVERYONES_GRUDGE) == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(119)  -- After completion cs\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 116 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVERYONES_GRUDGE)\n        player:setCharVar('EveryonesGrudgeStarted', 1)\n    elseif csid == 118 then\n        player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVERYONES_GRUDGE)\n        player:tradeComplete()\n        player:addFame(xi.fameArea.NORG, 20)\n        npcUtil.giveKeyItem(player, xi.keyItem.TONBERRY_PRIEST_KEY)\n        player:setCharVar('EveryonesGrudgeStarted', 0)\n        player:addTitle(xi.title.HONORARY_DOCTORATE_MAJORING_IN_TONBERRIES)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Norg/npcs/Mamaulabion.lua"]={["Path"]="scripts/zones/Norg/npcs/Mamaulabion.lua",["SHA256"]="3e034e7cefe50d234db41f401173161c18f763ea9bf836f4fe6a219e57337cf2",["Text"]="-----------------------------------\n-- Area: Norg\n--  NPC: Mamaulabion\n-- Starts and finishes Quest: Mama Mia\n-- !pos -57 -9 68 252\n\n--CSIDs for Mamaulabion\n--93 / 93 = Standard\n--191 / 191 = start quest\n--192 / 192 = quest accepted\n--193 / 193 = given an item\n--194 / 194 = given an item you already gave\n--195 / 195 = all 7 items given\n--196 / 196 = after 7 items, but need more time until reward is given\n--197 / 197 = reward\n--198 / 198 = after quest is complete\n--243 / 243 = get new ring if you dropped yours\n\n--I did alot of copy/pasting, so you may notice a reduncency on comments XD\n--But it can make it easier to follow aswell.\n\n--\"Upon completion of this quest, the above items no longer appear in the rewards list for defeating the Prime Avatars.\"\n--will require changing other avatar quests and making a variable for it all. (if this gets scripted, please remove this comment)\n\n-----------------------------------\nlocal ID = zones[xi.zone.NORG]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.MAMA_MIA) == xi.questStatus.QUEST_ACCEPTED then\n        -- check whether trade is an item with id 1202 to 1208\n        local tradedItem\n        local bitToSet\n        for i = xi.item.BOTTLE_OF_BUBBLY_WATER, xi.item.ANCIENTS_KEY do\n            if npcUtil.tradeHasExactly(trade, i) then\n                tradedItem = i\n                bitToSet = i - xi.item.BOTTLE_OF_BUBBLY_WATER\n                break\n            end\n        end\n\n        if tradedItem then\n            local mask = player:getCharVar('tradesMamaMia')\n            local wasSet = utils.mask.getBit(mask, bitToSet)\n\n            if wasSet then\n                player:startEvent(194, tradedItem) -- Traded an item you already gave\n            else\n                mask = utils.mask.setBit(mask, bitToSet, true)\n                player:setCharVar('tradesMamaMia', mask)\n\n                if utils.mask.isFull(mask, 7) then\n                    player:startEvent(195, tradedItem) -- Traded all seven items\n                else\n                    player:startEvent(193, tradedItem) -- Traded an item\n                end\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local mamaMia = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.MAMA_MIA)\n    local moonlitPath = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_MOONLIT_PATH)\n    local evokersRing = player:hasItem(xi.item.EVOKERS_RING)\n    local questday = player:getCharVar('MamaMia_date')\n\n    if\n        mamaMia == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.NORG) >= 4 and\n        moonlitPath == xi.questStatus.QUEST_COMPLETED\n    then\n        player:startEvent(191) -- Start Quest 'Mama Mia'\n\n    elseif mamaMia == xi.questStatus.QUEST_ACCEPTED then\n        local tradesMamaMia = player:getCharVar('tradesMamaMia')\n\n        if utils.mask.isFull(tradesMamaMia, 7) then\n            if GetSystemTime() < questday then\n                player:startEvent(196) --need to wait longer for reward\n            else\n                player:startEvent(197) --Reward\n            end\n        else\n            player:startEvent(192) -- During Quest \"Mama Mia\"\n        end\n\n    elseif mamaMia == xi.questStatus.QUEST_COMPLETED and evokersRing then\n        player:startEvent(198) -- New standard dialog after \"Mama Mia\" is complete\n\n    elseif mamaMia == xi.questStatus.QUEST_COMPLETED and not evokersRing then\n        player:startEvent(243) -- Quest completed, but dropped ring\n\n    else\n        player:startEvent(93) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 191 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.MAMA_MIA)\n    elseif csid == 193 then\n        player:confirmTrade()\n    elseif csid == 195 then\n        player:confirmTrade()\n        player:setCharVar('MamaMia_date', JstMidnight())\n    elseif csid == 197 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, 14625) -- Evokers Ring\n        else\n            player:addItem(xi.item.EVOKERS_RING) -- Evokers Ring\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.EVOKERS_RING) -- Evokers Ring\n            player:addFame(xi.fameArea.NORG, 40)\n            player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.MAMA_MIA)\n            player:setCharVar('tradesMamaMia', 0)\n        end\n    elseif csid == 243 then\n        if option == 1 then\n            player:delQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.MAMA_MIA)\n            player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.MAMA_MIA)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Norg/npcs/Muzaffar.lua"]={["Path"]="scripts/zones/Norg/npcs/Muzaffar.lua",["SHA256"]="9059673c2286abf5e4bdef58a5eeca62552b00bf16200f47e6081b4dbc5caa64",["Text"]="-----------------------------------\n-- Area: Norg\n--  NPC: Muzaffar\n-- Quests: Black Market\n-- !pos 16.678, -2.044, -14.600 252\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local count = trade:getItemCount()\n    local northernFurs = trade:hasItemQty(xi.item.NORTHERN_FUR, 4)\n    local easternPottery = trade:hasItemQty(xi.item.PIECE_OF_EASTERN_POTTERY, 4)\n    local southernMummies = trade:hasItemQty(xi.item.SOUTHERN_MUMMY, 4)\n\n    if\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.BLACK_MARKET) == xi.questStatus.QUEST_ACCEPTED or\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.BLACK_MARKET) == xi.questStatus.QUEST_COMPLETED\n    then\n        if northernFurs and count == 4 then\n            player:tradeComplete()\n            player:startEvent(17, xi.item.NORTHERN_FUR, xi.item.NORTHERN_FUR)\n        elseif easternPottery and count == 4 then\n            player:tradeComplete()\n            player:startEvent(18, xi.item.PIECE_OF_EASTERN_POTTERY, xi.item.PIECE_OF_EASTERN_POTTERY)\n        elseif southernMummies and count == 4 then\n            player:tradeComplete()\n            player:startEvent(19, xi.item.SOUTHERN_MUMMY, xi.item.SOUTHERN_MUMMY)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.BLACK_MARKET) == xi.questStatus.QUEST_ACCEPTED or\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.BLACK_MARKET) == xi.questStatus.QUEST_COMPLETED\n    then\n        player:startEvent(16)\n    else\n        player:startEvent(15)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 15 and option == 1 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.BLACK_MARKET)\n    elseif csid == 17 then\n        npcUtil.giveCurrency(player, 'gil', 1500)\n        if player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.BLACK_MARKET) == xi.questStatus.QUEST_ACCEPTED then\n            player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.BLACK_MARKET)\n        end\n\n        player:addFame(xi.fameArea.NORG, 30)\n        player:addTitle(xi.title.BLACK_MARKETEER)\n        player:startEvent(20)\n    elseif csid == 18 then\n        npcUtil.giveCurrency(player, 'gil', 2000)\n        if player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.BLACK_MARKET) == xi.questStatus.QUEST_ACCEPTED then\n            player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.BLACK_MARKET)\n        end\n\n        player:addFame(xi.fameArea.NORG, 40)\n        player:addTitle(xi.title.BLACK_MARKETEER)\n        player:startEvent(20)\n    elseif csid == 19 then\n        npcUtil.giveCurrency(player, 'gil', 3000)\n        if player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.BLACK_MARKET) == xi.questStatus.QUEST_ACCEPTED then\n            player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.BLACK_MARKET)\n        end\n\n        player:addFame(xi.fameArea.NORG, 50)\n        player:addTitle(xi.title.BLACK_MARKETEER)\n        player:startEvent(20)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Norg/npcs/Ryoma.lua"]={["Path"]="scripts/zones/Norg/npcs/Ryoma.lua",["SHA256"]="11a1afa0e21c76d629003586dc7c98205a0c76acbed7ed8018232777a0fab08b",["Text"]="-----------------------------------\n-- Area: Norg\n--  NPC: Ryoma\n-- Start and Finish Quest: 20 in Pirate Years, True Will\n-- !pos -23 0 -9 252\n-----------------------------------\nlocal ID = zones[xi.zone.NORG]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local twentyInPirateYears = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TWENTY_IN_PIRATE_YEARS)\n    local illTakeTheBigBox = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.I_LL_TAKE_THE_BIG_BOX)\n    local trueWill = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRUE_WILL)\n    local mLvl = player:getMainLvl()\n    local mJob = player:getMainJob()\n\n    if\n        twentyInPirateYears == xi.questStatus.QUEST_AVAILABLE and\n        mJob == xi.job.NIN and\n        mLvl >= 40\n    then\n        player:startEvent(133) -- Start Quest \"20 in Pirate Years\"\n    elseif\n        twentyInPirateYears == xi.questStatus.QUEST_ACCEPTED and\n        player:hasKeyItem(xi.keyItem.TRICK_BOX)\n    then\n        player:startEvent(134) -- Finish Quest \"20 in Pirate Years\"\n    elseif\n        illTakeTheBigBox == xi.questStatus.QUEST_COMPLETED and\n        trueWill == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(136) -- Start Quest \"True Will\"\n    elseif\n        player:hasKeyItem(xi.keyItem.OLD_TRICK_BOX) and\n        player:getCharVar('trueWillCS') == 0\n    then\n        player:startEvent(137)\n    elseif player:getCharVar('trueWillCS') == 1 then\n        player:startEvent(138)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 133 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TWENTY_IN_PIRATE_YEARS)\n        player:setCharVar('twentyInPirateYearsCS', 1)\n    elseif csid == 134 then\n        if player:getFreeSlotsCount() <= 1 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.ANJU)\n        else\n            player:delKeyItem(xi.keyItem.TRICK_BOX)\n            player:addItem(xi.item.ANJU)\n            player:addItem(xi.item.ZUSHIO)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.ANJU) -- Anju\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.ZUSHIO) -- Zushio\n            player:needToZone()\n            player:setCharVar('twentyInPirateYearsCS', 0)\n            player:addFame(xi.fameArea.NORG, 20)\n            player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TWENTY_IN_PIRATE_YEARS)\n        end\n    elseif csid == 136 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRUE_WILL)\n    elseif csid == 137 then\n        player:setCharVar('trueWillCS', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Norg/npcs/Stray_Cloud.lua"]={["Path"]="scripts/zones/Norg/npcs/Stray_Cloud.lua",["SHA256"]="4d1c22ca35d97328bfc26b0cf2558e465c595e4e7716a488460c759949eec322",["Text"]="-----------------------------------\n-- Area: Norg\n--  NPC: Stray Cloud\n-- Starts and Ends Quest: An Undying Pledge\n-- !pos-20.617, 1.097, -29.165, 133\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local anUndyingPledge = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.AN_UNDYING_PLEDGE)\n\n    if\n        anUndyingPledge == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.NORG) >= 4\n    then\n        player:startEvent(225) -- Start quest\n    elseif\n        anUndyingPledge == xi.questStatus.QUEST_ACCEPTED and\n        player:hasKeyItem(xi.keyItem.CALIGINOUS_BLADE)\n    then\n        player:startEvent(227) -- Quest Finish\n    elseif\n        anUndyingPledge == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('anUndyingPledgeCS') == 1\n    then\n        player:startEvent(228) -- Extra Dialogue\n    elseif\n        anUndyingPledge == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('anUndyingPledgeCS') == 2\n    then\n        player:startEvent(229) -- Extra Dialogue\n    elseif anUndyingPledge == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(230)\n    else\n        player:startEvent(231) -- Standard Conversation\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 225 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.AN_UNDYING_PLEDGE)\n        player:setCharVar('anUndyingPledgeCS', 1)\n    elseif\n        csid == 227 and\n        npcUtil.completeQuest(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.AN_UNDYING_PLEDGE, {\n            item = xi.item.LIGHT_BUCKLER,\n            fameArea = xi.fameArea.NORG,\n            fame = 40,\n            var = 'anUndyingPledgeCS',\n        })\n    then\n        player:delKeyItem(xi.keyItem.CALIGINOUS_BLADE)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Norg/npcs/Verctissa.lua"]={["Path"]="scripts/zones/Norg/npcs/Verctissa.lua",["SHA256"]="76dd2aa33ebbb6d303bd2ee017aa6032f71ad383925d2a45304f4d37dbde1263",["Text"]="-----------------------------------\n-- Area: Norg\n--  NPC: Verctissa\n-- Starts Quest: Trial Size Trial By Water\n-- !pos -13 1 -20 252\n-----------------------------------\nlocal ID = zones[xi.zone.NORG]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        trade:hasItemQty(xi.item.MINI_TUNING_FORK_OF_WATER, 1) and\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_SIZE_TRIAL_BY_WATER) == xi.questStatus.QUEST_ACCEPTED and\n        player:getMainJob() == xi.job.SMN\n    then\n        player:startEvent(200, 0, xi.item.MINI_TUNING_FORK_OF_WATER, 2, 20)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local trialSizeWater = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_SIZE_TRIAL_BY_WATER)\n\n    if\n        player:getMainLvl() >= 20 and\n        player:getMainJob() == xi.job.SMN and\n        trialSizeWater == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.NORG) >= 2\n    then\n        --Requires player to be Summoner at least lvl 20\n        player:startEvent(199, 0, xi.item.MINI_TUNING_FORK_OF_WATER, 2, 20)     --mini tuning fork of water, zone, level\n    elseif trialSizeWater == xi.questStatus.QUEST_ACCEPTED then\n        local waterFork = player:hasItem(xi.item.MINI_TUNING_FORK_OF_WATER)\n\n        if waterFork then\n            player:startEvent(111) --Dialogue given to remind player to be prepared\n        else\n            player:startEvent(203, 0, xi.item.MINI_TUNING_FORK_OF_WATER, 2, 20) --Need another mini tuning fork\n        end\n    elseif trialSizeWater == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(202) --Defeated Avatar\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 199 and option == 1 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MINI_TUNING_FORK_OF_WATER) --Mini tuning fork\n        else\n            player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_SIZE_TRIAL_BY_WATER)\n            player:addItem(xi.item.MINI_TUNING_FORK_OF_WATER)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MINI_TUNING_FORK_OF_WATER)\n        end\n    elseif csid == 203 and option == 1 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MINI_TUNING_FORK_OF_WATER) --Mini tuning fork\n        else\n            player:addItem(xi.item.MINI_TUNING_FORK_OF_WATER)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MINI_TUNING_FORK_OF_WATER)\n        end\n    elseif csid == 200 and option == 1 then\n        xi.teleport.to(player, xi.teleport.id.CLOISTER_OF_TIDES)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Northern_San_dOria/npcs/Ailbeche.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Ailbeche.lua",["SHA256"]="f345d3f9a06501bc26fbf2d9d09358bb9e5b74d502cc5bf9af6325745b44e18b",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Ailbeche\n-- Starts and Finishes Quest: Father and Son, Sharpening the Sword, A Boy's Dream (start)\n-- !pos 4 -1 24 231\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getCharVar('aBoysDreamCS') >= 3 then\n        if\n            npcUtil.tradeHasExactly(trade, xi.item.GIANT_SHELL_BUG) and\n            player:getCharVar('aBoysDreamCS') == 3\n        then\n            player:startEvent(15) -- During Quest \"A Boy's Dream\" (trading bug) madame ?\n        elseif\n            npcUtil.tradeHasExactly(trade, xi.item.ODONTOTYRANNUS) and\n            player:getCharVar('aBoysDreamCS') == 4\n        then\n            player:startEvent(47) -- During Quest \"A Boy's Dream\" (trading odontotyrannus)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local aBoysDream   = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_BOYS_DREAM)\n    local sharpenStone = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.SHARPENING_THE_SWORD)\n\n    -- Checking levels and jobs for af quest\n    local mLvl = player:getMainLvl()\n    local mJob = player:getMainJob()\n    local aBoysDreamCS = player:getCharVar('aBoysDreamCS')\n\n    if\n        aBoysDream == xi.questStatus.QUEST_AVAILABLE and\n        sharpenStone == xi.questStatus.QUEST_COMPLETED and\n        mJob == xi.job.PLD and\n        mLvl >= 50\n    then\n        if aBoysDreamCS == 0 then\n            player:startEvent(41) -- Start Quest 'A Boy's Dream' (long cs)\n        else\n            player:startEvent(40) -- Start Quest 'A Boy's Dream' (shot cs)\n        end\n    elseif aBoysDreamCS == 2 then\n        player:startEvent(46) -- During Quest 'A Boy's Dream'\n    elseif aBoysDreamCS == 3 then\n        player:startEvent(39) -- During Quest 'A Boy's Dream' (after exoroche cs)\n    elseif aBoysDreamCS == 4 then\n        player:startEvent(60) -- During Quest 'A Boy's Dream' (after trading bug) madame ?\n    elseif aBoysDreamCS == 5 then\n        player:startEvent(47) -- During Quest 'A Boy's Dream' (after trading odontotyrannus)\n    elseif aBoysDreamCS >= 6 then\n        player:startEvent(25) -- During Quest 'A Boy's Dream' (after Zaldon CS)\n    elseif\n        player:hasKeyItem(xi.keyItem.KNIGHTS_CONFESSION) and\n        player:getCharVar('UnderOathCS') == 6\n    then\n        player:startEvent(59) -- During Quest 'Under Oath' (he's going fishing in Jugner)\n    elseif player:getCharVar('UnderOathCS') == 8 then\n        player:startEvent(13) -- During Quest 'Under Oath' (After jugner CS)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- \"A Boy's Dream\"\n    if (csid == 41 or csid == 40) and option == 1 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_BOYS_DREAM)\n        player:setCharVar('aBoysDreamCS', 2)\n    elseif csid == 41 and option == 0 then\n        player:setCharVar('aBoysDreamCS', 1)\n    elseif csid == 15 and player:getCharVar('aBoysDreamCS') == 3 then\n        player:setCharVar('aBoysDreamCS', 4)\n    elseif csid == 47 and player:getCharVar('aBoysDreamCS') == 4 then\n        player:setCharVar('aBoysDreamCS', 5)\n    elseif csid == 25 and player:getCharVar('aBoysDreamCS') == 6 then\n        player:setCharVar('aBoysDreamCS', 7)\n    elseif csid == 59 then\n        player:setCharVar('UnderOathCS', 7)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Northern_San_dOria/npcs/Castilchat.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Castilchat.lua",["SHA256"]="5afe1899fce6eb00cc2e653e252c91c89d192bcecf78e67b9fa8a43f786bcc09",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Castilchat\n-- Starts Quest: Trial Size Trial by Ice\n-- !pos -186 0 107 231\n-----------------------------------\nlocal ID = zones[xi.zone.NORTHERN_SAN_DORIA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local count = trade:getItemCount()\n    if\n        trade:hasItemQty(xi.item.MINI_TUNING_FORK_OF_ICE, 1) and\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRIAL_SIZE_TRIAL_BY_ICE) == xi.questStatus.QUEST_ACCEPTED and\n        player:getMainJob() == xi.job.SMN and\n        count == 1\n    then -- Trade mini fork of ice\n        player:startEvent(734, 0, xi.item.MINI_TUNING_FORK_OF_ICE, 4, 20)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local trialSizeByIce = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRIAL_SIZE_TRIAL_BY_ICE)\n\n    if\n        player:getMainLvl() >= 20 and\n        player:getMainJob() == xi.job.SMN and\n        trialSizeByIce == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.SANDORIA) >= 2\n    then -- Requires player to be Summoner at least lvl 20\n        player:startEvent(733, 0, xi.item.MINI_TUNING_FORK_OF_ICE, 4, 20)     --mini tuning fork of ice, zone, level\n    elseif trialSizeByIce == xi.questStatus.QUEST_ACCEPTED then\n        local iceFork = player:hasItem(xi.item.MINI_TUNING_FORK_OF_ICE)\n\n        if iceFork then\n            player:startEvent(708) --Dialogue given to remind player to be prepared\n        else\n            player:startEvent(737, 0, xi.item.MINI_TUNING_FORK_OF_ICE, 4, 20) -- Need another mini tuning fork\n        end\n    elseif trialSizeByIce == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(736) -- Defeated Avatar\n    else\n        player:startEvent(711) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 733 and option == 1 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MINI_TUNING_FORK_OF_ICE)\n        else\n            player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRIAL_SIZE_TRIAL_BY_ICE)\n            player:addItem(xi.item.MINI_TUNING_FORK_OF_ICE)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MINI_TUNING_FORK_OF_ICE)\n        end\n    elseif csid == 734 and option == 0 or csid == 737 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MINI_TUNING_FORK_OF_ICE)\n        else\n            player:addItem(xi.item.MINI_TUNING_FORK_OF_ICE)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MINI_TUNING_FORK_OF_ICE)\n        end\n    elseif csid == 734 and option == 1 then\n        xi.teleport.to(player, xi.teleport.id.CLOISTER_OF_FROST)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Northern_San_dOria/npcs/Eperdur.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Eperdur.lua",["SHA256"]="61a78ae4de046de6700f7ea5ff325a1cbec92a8d8e33dcb2c511672dd8b18c7b",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Eperdur\n-- Starts and Finishes Quest: Healing the Land,\n-- !pos 129 -6 96 231\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local healingTheLand = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.HEALING_THE_LAND)\n    local sorceryOfTheNorth = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.SORCERY_OF_THE_NORTH)\n\n    if\n        healingTheLand == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.SANDORIA) >= 4 and\n        player:getMainLvl() >= 10\n    then\n        player:startEvent(681) -- Start quest \"Healing the Land\"\n    elseif\n        healingTheLand == xi.questStatus.QUEST_ACCEPTED and\n        player:hasKeyItem(xi.keyItem.SEAL_OF_BANISHING)\n    then\n        player:startEvent(682) -- During quest \"Healing the Land\"\n    elseif\n        healingTheLand == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.SEAL_OF_BANISHING)\n    then\n        player:startEvent(683) -- Finish quest \"Healing the Land\"\n    elseif\n        healingTheLand == xi.questStatus.QUEST_COMPLETED and\n        sorceryOfTheNorth == xi.questStatus.QUEST_AVAILABLE and\n        player:needToZone()\n    then\n        player:startEvent(684) -- New standard dialog after \"Healing the Land\"\n    elseif\n        healingTheLand == xi.questStatus.QUEST_COMPLETED and\n        sorceryOfTheNorth == xi.questStatus.QUEST_AVAILABLE and\n        not player:needToZone()\n    then\n        player:startEvent(685) -- Start quest \"Sorcery of the North\"\n    elseif\n        sorceryOfTheNorth == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.FEIYIN_MAGIC_TOME)\n    then\n        player:startEvent(686) -- During quest \"Sorcery of the North\"\n    elseif\n        sorceryOfTheNorth == xi.questStatus.QUEST_ACCEPTED and\n        player:hasKeyItem(xi.keyItem.FEIYIN_MAGIC_TOME)\n    then\n        player:startEvent(687) -- Finish quest \"Sorcery of the North\"\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 681 and option == 0 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.HEALING_THE_LAND)\n        npcUtil.giveKeyItem(player, xi.keyItem.SEAL_OF_BANISHING)\n    elseif csid == 683 then\n        if npcUtil.giveItem(player, xi.item.SCROLL_OF_TELEPORT_HOLLA) then\n            player:addTitle(xi.title.PILGRIM_TO_HOLLA)\n            player:needToZone(true)\n            player:addFame(xi.fameArea.SANDORIA, 40)\n            player:completeQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.HEALING_THE_LAND)\n        end\n    elseif csid == 685 and option == 0 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.SORCERY_OF_THE_NORTH)\n    elseif csid == 687 then\n        if npcUtil.giveItem(player, xi.item.SCROLL_OF_TELEPORT_VAHZL) then\n            player:delKeyItem(xi.keyItem.FEIYIN_MAGIC_TOME)\n            player:addFame(xi.fameArea.SANDORIA, 40)\n            player:completeQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.SORCERY_OF_THE_NORTH)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Northern_San_dOria/npcs/Excenmille.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Excenmille.lua",["SHA256"]="80fa96901c162ddd4e89bfbb3f185892bf078bd01527c88f2e5c98025e749c05",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Excenmille\n-- Type: Trust NPC, Ballista Pursuivant\n-- !pos -229.344 6.999 22.976 231\n-----------------------------------\nlocal ID = zones[xi.zone.NORTHERN_SAN_DORIA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal trustMemory = function(player)\n    local memories = 0\n    if player:hasKeyItem(xi.keyItem.BALLISTA_LICENSE) then\n        memories = memories + 2\n    end\n\n    -- 4 - Chocobo racing\n    --  memories = memories + 4\n    if player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.CLAWS_OF_THE_GRIFFON) then\n        memories = memories + 8\n    end\n\n    if player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BLOOD_OF_HEROES) then\n        memories = memories + 16\n    end\n\n    return memories\nend\n\nentity.onTrigger = function(player, npc)\n    local trustSandoria = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRUST_SANDORIA)\n    local trustBastok = player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.TRUST_BASTOK)\n    local trustWindurst = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TRUST_WINDURST)\n    local sandoriaFirstTrust = player:getCharVar('SandoriaFirstTrust')\n    local excenmilleTrustChatFlag = player:getLocalVar('ExcenmilleTrustChatFlag')\n    local rank3 = player:getRank(player:getNation()) >= 3 and 1 or 0\n\n    if\n        trustSandoria == xi.questStatus.QUEST_ACCEPTED and\n        (trustWindurst == xi.questStatus.QUEST_COMPLETED or trustBastok == xi.questStatus.QUEST_COMPLETED)\n    then\n        player:startEvent(897, 0, 0, 0, trustMemory(player), 0, 0, 0, rank3)\n    elseif\n        trustSandoria == xi.questStatus.QUEST_ACCEPTED and\n        sandoriaFirstTrust == 0\n    then\n        player:startEvent(893, 0, 0, 0, trustMemory(player), 0, 0, 0, rank3)\n    elseif\n        trustSandoria == xi.questStatus.QUEST_ACCEPTED and\n        sandoriaFirstTrust == 1 and\n        excenmilleTrustChatFlag == 0\n    then\n        player:startEvent(894)\n        player:setLocalVar('ExcenmilleTrustChatFlag', 1)\n    elseif\n        trustSandoria == xi.questStatus.QUEST_ACCEPTED and\n        sandoriaFirstTrust == 2\n    then\n        player:startEvent(895)\n    elseif\n        trustSandoria == xi.questStatus.QUEST_COMPLETED and\n        not player:hasSpell(xi.magic.spell.CURILLA) and\n        excenmilleTrustChatFlag == 0\n    then\n        player:startEvent(896, 0, 0, 0, 0, 0, 0, 0, rank3)\n        player:setLocalVar('ExcenmilleTrustChatFlag', 1)\n    else\n        player:startEvent(29)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- TRUST\n    if csid == 893 then\n        player:addSpell(xi.magic.spell.EXCENMILLE, { silentLog = true })\n        player:messageSpecial(ID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.EXCENMILLE)\n        player:setCharVar('SandoriaFirstTrust', 1)\n    elseif csid == 895 then\n        player:delKeyItem(xi.keyItem.RED_INSTITUTE_CARD)\n        player:messageSpecial(ID.text.KEYITEM_LOST, xi.keyItem.RED_INSTITUTE_CARD)\n        npcUtil.completeQuest(player, xi.questLog.SANDORIA, xi.quest.id.sandoria.TRUST_SANDORIA, {\n            keyItem = xi.keyItem.SAN_DORIA_TRUST_PERMIT,\n            title = xi.title.THE_TRUSTWORTHY,\n            var = 'SandoriaFirstTrust'\n        })\n        player:messageSpecial(ID.text.CALL_MULTIPLE_ALTER_EGO)\n    elseif csid == 897 then\n        player:addSpell(xi.magic.spell.EXCENMILLE, { silentLog = true })\n        player:messageSpecial(ID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.EXCENMILLE)\n        player:delKeyItem(xi.keyItem.RED_INSTITUTE_CARD)\n        player:messageSpecial(ID.text.KEYITEM_LOST, xi.keyItem.RED_INSTITUTE_CARD)\n        npcUtil.completeQuest(player, xi.questLog.SANDORIA, xi.quest.id.sandoria.TRUST_SANDORIA, {\n            keyItem = xi.keyItem.SAN_DORIA_TRUST_PERMIT\n        })\n    end\nend\n\nreturn entity\n"},["scripts/zones/Northern_San_dOria/npcs/Gulmama.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Gulmama.lua",["SHA256"]="6aa0b2ad53f4a508f8d1f4c635598bac8b72781f9702d3c2c62b861cad9f795a",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Gulmama\n-- Starts and Finishes Quest: Trial by Ice\n-- Involved in Quest: Class Reunion\n-- !pos -186 0 107 231\n-----------------------------------\nlocal ID = zones[xi.zone.NORTHERN_SAN_DORIA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local trialByIce = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRIAL_BY_ICE)\n    local classReunion = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION)\n    local classReunionProgress = player:getCharVar('ClassReunionProgress')\n\n    -----------------------------------\n    -- Class Reunion\n    if classReunion == 1 and classReunionProgress == 4 then\n        player:startEvent(713, 0, xi.item.ICE_PENDULUM, 0, 0, 0, 0, 0, 0) -- he gives you an ice pendulum and wants you to go to Cloister of Frost\n    elseif\n        classReunion == 1 and\n        classReunionProgress == 5 and\n        not player:hasItem(xi.item.ICE_PENDULUM)\n    then\n        player:startEvent(712, 0, xi.item.ICE_PENDULUM, 0, 0, 0, 0, 0, 0) -- lost the ice pendulum need another one\n    -----------------------------------\n    elseif\n        (trialByIce == xi.questStatus.QUEST_AVAILABLE and player:getFameLevel(xi.fameArea.SANDORIA) >= 6) or\n        (trialByIce == xi.questStatus.QUEST_COMPLETED and GetSystemTime() > player:getCharVar('TrialByIce_date'))\n    then\n        player:startEvent(706, 0, xi.keyItem.TUNING_FORK_OF_ICE) -- Start and restart quest 'Trial by ice'\n    elseif\n        trialByIce == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.TUNING_FORK_OF_ICE) and\n        not player:hasKeyItem(xi.keyItem.WHISPER_OF_FROST)\n    then\n        player:startEvent(718, 0, xi.keyItem.TUNING_FORK_OF_ICE) -- Defeat against Shiva : Need new Fork\n    elseif\n        trialByIce == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.WHISPER_OF_FROST)\n    then\n        player:startEvent(707, 0, xi.keyItem.TUNING_FORK_OF_ICE, 4)\n    elseif\n        trialByIce == xi.questStatus.QUEST_ACCEPTED and\n        player:hasKeyItem(xi.keyItem.WHISPER_OF_FROST)\n    then\n        local numitem = 0\n\n        if player:hasItem(xi.item.SHIVAS_CLAWS) then\n            numitem = numitem + 1\n        end  -- Shiva's Claws\n\n        if player:hasItem(xi.item.ICE_BELT) then\n            numitem = numitem + 2\n        end  -- Ice Belt\n\n        if player:hasItem(xi.item.ICE_RING) then\n            numitem = numitem + 4\n        end  -- Ice Ring\n\n        if player:hasItem(xi.item.BOTTLE_OF_RUST_B_GONE) then\n            numitem = numitem + 8\n        end   -- Rust 'B' Gone\n\n        if player:hasSpell(xi.magic.spell.SHIVA) then\n            numitem = numitem + 32\n        end  -- Ability to summon Shiva\n\n        player:startEvent(709, 0, xi.keyItem.TUNING_FORK_OF_ICE, 4, 0, numitem)\n    else\n        player:startEvent(710) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 706 and option == 1 then\n        if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRIAL_BY_ICE) == xi.questStatus.QUEST_COMPLETED then\n            player:delQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRIAL_BY_ICE)\n        end\n\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRIAL_BY_ICE)\n        player:setCharVar('TrialByIce_date', 0)\n        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_ICE)\n    elseif csid == 718 then\n        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_ICE)\n    elseif csid == 709 then\n        local item = 0\n\n        if option == 1 then\n            item = xi.item.SHIVAS_CLAWS -- Shiva's Claws\n        elseif option == 2 then\n            item = xi.item.ICE_BELT -- Ice Belt\n        elseif option == 3 then\n            item = xi.item.ICE_RING -- Ice Ring\n        elseif option == 4 then\n            item = xi.item.BOTTLE_OF_RUST_B_GONE  -- Rust 'B' Gone\n        end\n\n        if player:getFreeSlotsCount() == 0 and (option ~= 5 or option ~= 6) then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, item)\n        else\n            if option == 5 then\n                npcUtil.giveCurrency(player, 'gil', 10000)\n            elseif option == 6 then\n                player:addSpell(xi.magic.spell.SHIVA) -- Avatar\n                player:messageSpecial(ID.text.SHIVA_UNLOCKED, 0, 0, 4)\n            else\n                player:addItem(item)\n                player:messageSpecial(ID.text.ITEM_OBTAINED, item) -- Item\n            end\n\n            player:addTitle(xi.title.HEIR_OF_THE_GREAT_ICE)\n            player:delKeyItem(xi.keyItem.WHISPER_OF_FROST) --Whisper of Frost, as a trade for the above rewards\n            player:setCharVar('TrialByIce_date', JstMidnight())\n            player:addFame(xi.fameArea.SANDORIA, 60)\n            player:completeQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRIAL_BY_ICE)\n        end\n    elseif csid == 713 or csid == 712 then\n        if player:getFreeSlotsCount() ~= 0 then\n            player:addItem(xi.item.ICE_PENDULUM)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.ICE_PENDULUM)\n            player:setCharVar('ClassReunionProgress', 5)\n        else\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.ICE_PENDULUM)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Northern_San_dOria/npcs/Miaux.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Miaux.lua",["SHA256"]="791ce7ffcabeab0f5fdb5269be8fd3e876d0ac7a2ce8b3223c65aaae43bb336e",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Miaux\n-- Type: Quest Giver\n-- !pos -169.127 2.999 158.677 231\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local aCraftsmansWork = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_CRAFTSMANS_WORK)\n\n    if\n        player:getMainJob() == xi.job.DRG and\n        player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL and\n        aCraftsmansWork == xi.questStatus.QUEST_AVAILABLE\n    then\n        if player:getCharVar('has_seen_drgaf1_quest_already') == 0 then\n            player:startEvent(73)\n        else -- If player has seen the big cut scene, give them a smaller one.\n            player:startEvent(71)\n        end\n    elseif\n        aCraftsmansWork == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.ALTEPA_POLISHING_STONE)\n    then\n        player:startEvent(69)\n    elseif aCraftsmansWork == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(70)\n    else\n        player:startEvent(11)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 73 and option == 2 then -- first part of long CS -- declines questgiver\n        player:setCharVar('has_seen_drgaf1_quest_already', 1)\n    elseif (csid == 73 or csid == 71) and option == 1 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_CRAFTSMANS_WORK)\n        player:setCharVar('has_seen_drgaf1_quest_already', 0)\n        player:setCharVar('aCraftsmanWork', 1)\n    elseif csid == 70 then -- This is only if player has Altepa Polishing Stone\n        if npcUtil.giveItem(player, xi.item.PEREGRINE) then\n            player:setCharVar('aCraftsmanWork', 0)\n            player:delKeyItem(xi.keyItem.ALTEPA_POLISHING_STONE)\n            player:addFame(xi.fameArea.SANDORIA, 20)\n            player:completeQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_CRAFTSMANS_WORK)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Northern_San_dOria/npcs/Morjean.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Morjean.lua",["SHA256"]="61e65a3673fba633810295f4083f4b8e5c54a05f3f824dfbe2c74343d31d6d21",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Morjean\n-- Involved in Quest: A Squire's Test II (Optional), The Holy Crest\n-- !pos 99 0 116 231\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local theHolyCrest = player:getCharVar('TheHolyCrest_Event')\n\n    if theHolyCrest == 2 then\n        player:startEvent(65)\n    elseif\n        (theHolyCrest == 3 and player:hasItem(xi.item.WYVERN_EGG)) or\n        theHolyCrest == 4\n    then -- Wyvern Egg\n        player:startEvent(62)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 65 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_HOLY_CREST)\n        player:setCharVar('TheHolyCrest_Event', 3)\n    elseif csid == 62 and option == 0 then\n        player:setCharVar('TheHolyCrest_Event', 4)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Northern_San_dOria/npcs/Narcheral.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Narcheral.lua",["SHA256"]="1465885379e3df4e3e1905f7da860597be60cde73090fd8f1df53c0ccd1e68eb",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Narcheral\n-- Starts and Finishes Quest: Messenger from Beyond, Prelude of Black and White (Finish), Pieuje's Decision (Finish)\n-- !pos 129 -11 126 231\n-----------------------------------\nlocal ID = zones[xi.zone.NORTHERN_SAN_DORIA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.PIEUJES_DECISION) == xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHasExactly(trade, xi.item.TAVNAZIAN_MASK)\n    then\n        player:startEvent(692)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 692 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.HEALERS_BLIAUT) -- Healer's Bliaut\n        else\n            player:addTitle(xi.title.PARAGON_OF_WHITE_MAGE_EXCELLENCE)\n            player:setCharVar('pieujesDecisionCS', 0)\n            player:addItem(xi.item.HEALERS_BLIAUT)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.HEALERS_BLIAUT) -- Healer's Bliaut\n            player:tradeComplete()\n            player:addFame(xi.fameArea.SANDORIA, 20)\n            player:completeQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.PIEUJES_DECISION)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Northern_San_dOria/npcs/Nonterene.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Nonterene.lua",["SHA256"]="41d01cbe1ea4776fa869f10d3e54476297008b6b04aca055a70095b2342cb794",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Nonterene\n-- Type: Adventurer's Assistant NPC\n-- !pos -6.347 0.000 -11.265 231\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.EXIT_THE_GAMBLER) == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(523)\n    else\n        player:startEvent(503)\n    end\nend\n\nreturn entity\n"}};
